package com.campus.trade.ai.dispute;
import com.campus.trade.common.context.UserContext; import com.campus.trade.common.exception.*; import com.campus.trade.dispute.entity.Dispute; import com.campus.trade.dispute.service.DisputeService; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.transaction.support.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import java.util.concurrent.Executor;
@Service public class DisputeAgentService { private final DisputeService disputes; private final DisputeAgentRunMapper runs; private final DisputeAgentProperties props; private final DisputeRuleService ruleService; private final com.fasterxml.jackson.databind.ObjectMapper json; private final com.campus.trade.ai.dispute.DisputeAgentServiceModel model; private final Executor executor; public DisputeAgentService(DisputeService d,DisputeAgentRunMapper r,DisputeAgentProperties p,DisputeRuleService rs,ObjectMapper j,DisputeAgentServiceModel m,@Qualifier("disputeAiAssistExecutor")Executor e){disputes=d;runs=r;props=p;ruleService=rs;json=j;model=m;executor=e;} @Transactional public DisputeAgentRunVO assist(Long id){if(!props.isEnabled())return new DisputeAgentRunVO(null,"DISABLED",null,null,null,"纠纷 AI 辅助已关闭",null); var d=disputes.adminDetail(id); if(!List.of(0,1).contains(d.status()))throw new BizException(ErrorCode.CONFLICT,"已裁决纠纷不能触发 AI 辅助"); var old=runs.selectSucceeded(id,d.evidenceVersion()); if(old!=null)return DisputeAgentRunVO.from(old); Map<String,Object> snap=json.convertValue(d,Map.class); String raw; try{raw=json.writeValueAsString(snap);}catch(Exception e){throw new IllegalStateException(e);} var run=new DisputeAgentRunEntity();run.setRunId(UUID.randomUUID().toString());run.setDisputeId(id);run.setOrderId(d.orderId());run.setStatus(DisputeAgentStatus.PENDING.name());run.setAttempt(0);run.setModelName("configured");run.setRuleVersion(ruleService.currentVersion());run.setSubmittedEvidenceVersion(d.evidenceVersion());run.setInputSnapshot(raw);run.setInputDigest(digest(raw));run.setTriggeredBy(UserContext.requireCurrentUser().userId());runs.insert(run);Runnable task=()->execute(run);if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){executor.execute(task);}});else executor.execute(task);return DisputeAgentRunVO.from(run); } public DisputeAgentRunVO latest(Long id){var x=runs.selectLatest(id);return x==null?null:DisputeAgentRunVO.from(x);} @Transactional public DisputeAgentRunVO adopt(Long id,String runId,String action){var x=runs.selectByRunId(runId);if(x==null||!id.equals(x.getDisputeId())||!DisputeAgentStatus.SUCCEEDED.name().equals(x.getStatus()))throw new BizException(ErrorCode.NOT_FOUND,"有效 AI 建议不存在");runs.markAdopted(runId,UserContext.requireCurrentUser().userId(),action);return latest(id);} private void execute(DisputeAgentRunEntity run){if(runs.markRunning(run.getRunId())==0)return;try{var current=disputes.adminDetail(run.getDisputeId());if(!List.of(0,1).contains(current.status())||!Objects.equals(current.evidenceVersion(),run.getSubmittedEvidenceVersion())){runs.markStale(run.getRunId(),"VERSION_OR_STATUS_CHANGED");return;}var result=model.analyze(json.readValue(run.getInputSnapshot(),Map.class)); if(runs.markSuccess(run.getRunId(),json.writeValueAsString(result))==0)runs.markStale(run.getRunId(),"VERSION_OR_STATUS_CHANGED");}catch(Exception e){runs.markFailure(run.getRunId(),DisputeAgentStatus.INVALID_OUTPUT.name(),"AI_OUTPUT_INVALID",e.getMessage());}} private String digest(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
